-- Generated by tools/prepare_story.py from docs/story.md; edit the reviewed script.
return {
    {key="after-01", phase="after", level=1, lines={
        {"mara", "Landing's clear. The mooring ring is all rust, but the rope held, and so did the Marigold, my skiff."},
        {"elena", "Tide marks up the quay: green at my knee, white at my waist. Someone watched this water."},
        {"adrian", "Splendid. Water next, please. I fund wells; I don't dig them."},
    }},
    {key="restore-01", phase="restore", level=1, building="Spring well", lines={
        {"mara", "First bucket! Taste it, Elena. No salt, no rust, no goat."},
        {"elena", "Sweet. And the rope brought up a scrap of harbour chart. Wait, a flash by the cliff!"},
        {"mara", "Let's ask. Two flashes out... and two back! Someone's down there."},
    }},
    {key="after-02", phase="after", level=2, lines={
        {"elena", "Working theory: Mara's lamp hit wet jade and bounced off the cliff. A reflection."},
        {"mara", "A reflection that waits its turn? Your jade has manners."},
        {"elena", "A breath's delay is distance. Tonight my lamp stays in its sack. If it flashes, I'll eat the theory."},
    }},
    {key="after-03", phase="after", level=3, lines={
        {"elena", "Midnight, lamp in its sack, ceiba roots at my back, and two flashes anyway. Reflection withdrawn."},
        {"mara", "Put it in your notes: \"Mara was right.\""},
        {"elena", "Noted. In the margin, in pencil."},
    }},
    {key="after-04", phase="after", level=4, lines={
        {"tomas", "Mind the third post; it bites. Tomas Reed. I keep this harbour."},
        {"mara", "Keep it? We were told the place has been empty for years."},
        {"tomas", "It has. Someone still has to count the tides. You mended my well, I see. Thank you."},
    }},
    {key="after-05", phase="after", level=5, lines={
        {"elena", "Mr Reed, a lamp answered Mara from under the cliff. Whose is it?"},
        {"tomas", "Ines and I wired a warning lamp under that far cliff. The storm cut its cable."},
        {"mara", "No cable, no lamp. And it still winked at me twice. Rude."},
    }},
    {key="after-06", phase="after", level=6, lines={
        {"tomas", "The cable ends at a break up this channel. I spliced it by lantern. The rain won."},
        {"elena", "\"Ines and I,\" you said. Who is Ines?"},
        {"tomas", "She worked it with me. Another time. First, my father's cabin needs a roof."},
    }},
    {key="after-07", phase="after", level=7, lines={
        {"mara", "Sawmill path! The roof fell in, but the big saw is still in its frame, rusty and smug."},
        {"tomas", "Once the workshop is mended, it will cut again. Then I can build a reel for the cable."},
        {"elena", "Then the workshop comes first. Timber is the road to everything else here."},
    }},
    {key="after-08", phase="after", level=8, lines={
        {"elena", "Adrian had the radio talking a minute ago. Now it's in pieces on the paving."},
        {"adrian", "Salt in the contacts. Everything out here dies of salt. Pass the screwdriver."},
        {"mara", "I've watched salt eat a hinge overnight. Believable."},
    }},
    {key="after-09", phase="after", level=9, lines={
        {"elena", "Hands off, Adrian! These carvings are older than your bank."},
        {"adrian", "It leaned on me. What are they?"},
        {"elena", "A river, a tide, and a figure with a lamp at a shutter. Every watch had a keeper."},
    }},
    {key="after-10", phase="after", level=10, lines={
        {"mara", "Tide chamber! Water's licking the third step, and the stair runs on down under the inlet."},
        {"elena", "Marks on every wall, one above another. Somebody measured this water for years."},
        {"tomas", "It reaches the far station. I locked the room at its end myself. The key stays on my belt."},
    }},
    {key="after-11", phase="after", level=11, lines={
        {"mara", "The colonnade fell like dominoes. Behind it: planks, dry as bread."},
        {"tomas", "Good timber, the first I've seen in years. The workshop's saw wants oil and time."},
        {"adrian", "Wood! At last, something on this island I can put on an invoice."},
    }},
    {key="after-12", phase="after", level=12, lines={
        {"tomas", "First timber, first reel, shaped by hand. A drop of lamp oil on the spindle and it turns."},
        {"mara", "It wobbles."},
        {"tomas", "It will wind cable. Loose coils lie round the mooring posts. Bring them in."},
    }},
    {key="after-13", phase="after", level=13, lines={
        {"elena", "From the spire I can see the far cliff. A dark square under the ledge. A shutter?"},
        {"tomas", "The far shutter. It has been shut since the storm. It should still be."},
        {"mara", "Then someone forgot to tell it."},
    }},
    {key="after-14", phase="after", level=14, lines={
        {"elena", "Every pillar is a tide table, and every great storm is cut into the stone."},
        {"adrian", "Are there copies of these? Somewhere off the island, say. Safer, surely."},
        {"elena", "Stone doesn't copy itself. I'm sketching all of it."},
    }},
    {key="after-15", phase="after", level=15, lines={
        {"mara", "The aqueduct's broken in three places. So is the cable. The same three."},
        {"elena", "Not coincidence. The cable ran along the arches, and the storm took both."},
        {"tomas", "Then we wind from the first arch. Watch your feet."},
    }},
    {key="after-16", phase="after", level=16, lines={
        {"mara", "The Overlook! The harbour mouth, the far cliff, and every wave I've ever sworn at."},
        {"elena", "And the dark shutter. If anyone's down there, they'll see a lamp from here."},
        {"tomas", "Then we want a camp with a proper watch. Lamp oil, a book, someone awake."},
    }},
    {key="restore-16", phase="restore", level=16, building="Expedition camp", lines={
        {"mara", "Camp's up and the night watch is posted. Is that your father's watch book, Tomas?"},
        {"tomas", "Off the cabin shelf. The roof is on, the workshop saw turns. First page is the keeper's."},
        {"keeper", "When the tide covers the reef, open the warning shutter. Let the boats see the light."},
        {"mara", "I flashed two from the lamp stand. Three came back, a pause before the third!"},
        {"tomas", "Ines kept the far shutter once. Nobody has, since the storm."},
        {"elena", "Nobody. And yet three flashes. Who should answer?"},
    }, prompt="Who should answer the signal?", choices={
        {id="mara", label="Ask Mara to reply", lines={
            {"mara", "One long flash, so they know we've seen them."},
            {"tomas", "Keep it steady. There. They'll know somebody's on watch."},
        }},
        {id="tomas", label="Ask Tomas to reply", lines={
            {"tomas", "One long flash means we are listening. Let me show you."},
            {"mara", "Here. Take my lamp. It sticks if you try to be gentle."},
        }},
    }},
    {key="after-17", phase="after", level=17, lines={
        {"mara", "One long flash went out at dusk. Nothing since. Moss has moved into my boots."},
        {"elena", "Before, they always answered the same night. This silence is a message too. They're thinking."},
        {"tomas", "Or deciding whether we're friends. I'd wait, too."},
    }},
    {key="after-18", phase="after", level=18, lines={
        {"elena", "Two wells side by side: one sweet, one brine. The sea reaches under this ridge."},
        {"adrian", "Delightful. Here's the pump order, signed. I read the number; the number was charming."},
        {"elena", "The rest of the page exists, Adrian. Someday you must try it."},
    }},
    {key="after-19", phase="after", level=19, lines={
        {"elena", "Reflection is long dead. What's left: someone alive, with a lamp, who knows the old code."},
        {"tomas", "Or someone who learned it from those who did."},
        {"mara", "Then we'll be good company. Highest step tomorrow, at dusk."},
    }},
    {key="before-20", phase="before", level=20, lines={
        {"mara", "Highest step, dusk. The tide is covering the reef, just as the book says. Mind my lamp: it sticks."},
        {"tomas", "Steady hands, then. We want them to know somebody is listening."},
        {"elena", "Our long flash, then we wait. Whatever comes, I'm writing it down."},
    }},
    {key="after-20", phase="after", level=20, lines={
        {"mara", "Our long flash crosses the gap... and a short one comes back!"},
        {"elena", "Mind the gaps between flashes: slow, uneven. That's no wire. That's a hand on a shutter."},
        {"tomas", "Then somebody is standing in that dark room, on the wrong side of the water."},
    }},
    {key="before-21", phase="before", level=21, lines={
        {"mara", "One long flash from our lamp. A lopsided flash back. That's no relay, that's a wrist."},
        {"elena", "A wrist on a schedule. Same count every night, never quite on time. I'm writing it down."},
        {"tomas", "The terrace path runs straight at that shutter. Mind the loose stones. Green arrows hold."},
    }},
    {key="after-21", phase="after", level=21, lines={
        {"elena", "The vines along the path are cut clean. Not torn, not rotted. Cut, and recently."},
        {"mara", "A machete, or a very tidy goat."},
        {"tomas", "The islanders know every track here. Give them a market and they'll come back."},
    }},
    {key="restore-21", phase="restore", level=21, building="Jungle market", lines={
        {"mara", "Market's open, and the islanders who work the quay are back! Adrian bought all the string."},
        {"elena", "The builders found this behind a stall beam: a sealed food bag, dated last week."},
        {"tomas", "Dated, dry, and hidden from the damp. Somebody is out here, and means to stay."},
        {"adrian", "I like them already. Anyone who dates their lunch has my full respect."},
    }},
    {key="after-22", phase="after", level=22, lines={
        {"mara", "Boot prints in the wet clay. One pair going up the stair, one pair coming down."},
        {"elena", "One person. Short stride, left heel worn. Smaller than you, Mara."},
        {"mara", "Rude, and probably correct. Keep walking."},
    }},
    {key="after-23", phase="after", level=23, lines={
        {"mara", "I'm fine. The lamp's fine. The moss and I will speak later."},
        {"tomas", "You found the loose slab. The prints step round it. They knew it was there."},
        {"elena", "Then someone who has climbed this stair before. Many times. Noted."},
    }},
    {key="after-24", phase="after", level=24, lines={
        {"adrian", "Elena, my backers are the Meridian Society. Bankers with an interest in old harbours."},
        {"elena", "Bankers on a dig. What do they want?"},
        {"adrian", "Tidy reports. Their man Kessler rings now and then. Excuse me, the ridge has the signal."},
    }},
    {key="after-25", phase="after", level=25, lines={
        {"elena", "Nine replies logged since we landed. All at dusk or dawn. Never at noon."},
        {"mara", "A night shift. I respect that."},
        {"tomas", "Dusk and dawn, when the tide covers the reef. The old order, kept to the letter."},
    }},
    {key="after-26", phase="after", level=26, lines={
        {"tomas", "The quay wall is losing stones. It wants dressed stone, and the quarrymen sell to a post."},
        {"adrian", "A trading post, then! Hand me the terms and a pen. I never read, I trust faces."},
        {"elena", "That is the least comforting sentence I have heard all week."},
    }},
    {key="after-27", phase="after", level=27, lines={
        {"mara", "New pattern! Long, short, short. Until now it was one lopsided flash."},
        {"elena", "A mechanism repeats itself. A person who wants noticing changes the tune."},
        {"tomas", "Then we answer politely. Whoever it is has waited a long while to be heard."},
    }},
    {key="after-28", phase="after", level=28, lines={
        {"mara", "The prints run down to the shore and stop dead at the water's edge."},
        {"elena", "Tides wipe prints. But where does a person go from here?"},
        {"tomas", "Not swimming. Nobody swims that gap. Not twice."},
    }},
    {key="after-29", phase="after", level=29, lines={
        {"tomas", "This lamp bracket was bent flat in the storm. Someone has hammered it straight."},
        {"mara", "At our lookout? Right beside my lamp, and I never saw them."},
        {"elena", "Straightened, oiled, the lens wiped clean. A visitor who tidies. Hm."},
    }},
    {key="after-30", phase="after", level=30, lines={
        {"mara", "Red from the far lamp! The reef's under the tide, dead ahead! Hauling the Marigold round!", story.SHOUT},
        {"tomas", "My father's order, kept in red glass. Whoever it is keeps it better than I did."},
        {"mara", "Soaked, alive, and in somebody's debt. I want to say thank you to a face."},
    }},
    {key="after-31", phase="after", level=31, lines={
        {"mara", "Biscuit for breakfast, biscuit for lunch. For one warm loaf I'd trade my lamp. Almost."},
        {"elena", "The mill wants repairs first. My notes: dusk and dawn, but only when the tide covers the reef."},
        {"tomas", "Hours follow the water. My father flashed one for each hour of the rise."},
    }},
    {key="after-32", phase="after", level=32, lines={
        {"tomas", "The wire ran down the stair to the tide room under the far cliff. I bolted it."},
        {"mara", "Then who gets in to work a shutter? High water floods that stair."},
        {"elena", "Someone who crosses at low water and waits on the ledge as it rises. How, I don't yet know."},
    }},
    {key="after-33", phase="after", level=33, lines={
        {"elena", "Theory. The Meridian Society wants treasure, and Kessler's men are scouting ahead of us."},
        {"adrian", "Kessler? Dull little man. He sends lawyers, never anyone who can climb a stair."},
        {"mara", "Scouts who answer my lamp. Very polite, for treasure hunters."},
    }},
    {key="after-34", phase="after", level=34, lines={
        {"tomas", "Treasure hunters take. The brass bell is still on its hook, and the lens still whole."},
        {"elena", "Kessler's men: withdrawn. Struck from the notebook."},
        {"mara", "A burglar who tidies up. I think we have a colleague."},
    }},
    {key="after-35", phase="after", level=35, lines={
        {"mara", "I was standing there two seconds ago. A stone the size of a stool is standing there now."},
        {"tomas", "The quay wall. Three stones down this month. We need to know which hours are safe."},
        {"elena", "The old tide clock would tell us. If it had a tower, and hands, and a dial."},
    }},
    {key="after-36", phase="after", level=36, lines={
        {"mara", "Fished a brass disc out of the moss well. Heavy, green, covered in numbers."},
        {"elena", "A tide dial, marked for this very harbour! In a tower it would tell us the safe hours."},
        {"tomas", "Then give it a tower. My father set his whole day by that clock."},
    }},
    {key="restore-36", phase="restore", level=36, building="Tide clock tower", lines={
        {"mara", "The tide clock ticks! Mill bread in my pocket, quarry stone coming in. Gloriously busy."},
        {"elena", "Green hours, safe on the quay. Red hours, stay off. Look where the red band begins."},
        {"tomas", "That is the crack's height. It runs into the quay wall, and the sea comes through it."},
        {"elena", "And the flashes come as the red hours begin. Whoever it is keeps the water's hours."},
    }},
    {key="after-37", phase="after", level=37, lines={
        {"mara", "Green hours, so we walked the foot of the wall. Look: a rope, knotted for climbing."},
        {"elena", "Fresh hemp, new knots. Whoever climbs here expects the tide back soon."},
        {"tomas", "Tied to a ring I set myself, years ago. Mind the loops. They hold."},
    }},
    {key="after-38", phase="after", level=38, lines={
        {"tomas", "The harbour strongroom keeps the old bearings. It stays shut until the plaza is mended."},
        {"mara", "Adrian alphabetises his socks, Tomas. He'll want it open yesterday."},
        {"adrian", "Guilty. I like a tidy shelf."},
    }},
    {key="after-39", phase="after", level=39, lines={
        {"elena", "The crack is an arm's length wide. Adrian's string, at last, is useful."},
        {"mara", "Hero of the market. I'll tell him."},
        {"tomas", "A finger's width when I shut the tide room. The spring tides have opened it."},
    }},
    {key="before-40", phase="before", level=40, lines={
        {"elena", "The green hours open soon. I want this crack traced to the end of the wall."},
        {"mara", "And I want to meet whoever tied those knots. Both, then. Let's walk."},
        {"tomas", "Slowly. The wall is older than my patience, and in a worse mood."},
    }},
    {key="after-40", phase="after", level=40, lines={
        {"elena", "A note under this stone, pencil fresh: “Wall unsafe. I. R.” The crack runs through the wall."},
        {"mara", "The islanders who work the quay pass this wall daily. Tell them today. Short, polite, right."},
        {"tomas", "I. R. I know that R. The harbour register will tell us, once the plaza is open."},
    }},
    {key="before-41", phase="before", level=41, lines={
        {"elena", "Pencil on stone: a warning for the quay, signed with two initials. Someone measured this wall."},
        {"mara", "A stranger with manners, flashing at us from a room the sea floods."},
        {"tomas", "Every boat signed the harbour register. Find it, and I'll know that R."},
    }},
    {key="after-41", phase="after", level=41, lines={
        {"mara", "Under the reed hut's floor: a book the size of a door. It smells like a wet goat."},
        {"elena", "The harbour register! Every boat that ever tied up signed in ink."},
        {"tomas", "It wants a dry table. Open the plaza and I'll read it to you."},
    }},
    {key="restore-41", phase="restore", level=41, building="Harbour plaza", lines={
        {"tomas", "Page nine, over and over: that R like a fishhook. Ines Reed. My sister."},
        {"mara", "Reed. As in Tomas Reed. As in \"Ines and I wired it\", you dark horse."},
        {"tomas", "I should have said so. After the storm her name got hard to say."},
        {"elena", "Her last entry is the night of the storm. The note under the stone is this week's."},
    }},
    {key="after-42", phase="after", level=42, lines={
        {"elena", "Tomas, forgive me, but I need the true order of that night."},
        {"tomas", "The wall cracked, so I closed the tide room. Ines left for the plans. That was all."},
        {"mara", "And you stayed to mind the lamp. Of course you did."},
    }},
    {key="after-43", phase="after", level=43, lines={
        {"tomas", "Then the storm cut the cable. I spliced until dawn and left my pliers at the break."},
        {"elena", "And Ines?"},
        {"tomas", "She never came up the cliff road. I kept the arrows painted green and watched it anyway."},
    }},
    {key="after-44", phase="after", level=44, lines={
        {"tomas", "I have thought it through. Ines must have drowned, and someone is borrowing her initials."},
        {"elena", "It fits what we hold. I do not like how neatly it fits."},
        {"mara", "A stranger who signs with her fishhook R? Let's find a second sample of that hand."},
    }},
    {key="after-45", phase="after", level=45, lines={
        {"elena", "A tide table chalked inside the vault door, and this week's tides ticked off in pencil."},
        {"tomas", "Hooked ticks. I taught that tally to one person. She added the hook to annoy me."},
        {"tomas", "I was wrong. Nobody borrows a tally. Ines is alive, and she is writing."},
    }},
    {key="after-46", phase="after", level=46, lines={
        {"mara", "Dawn, and the far shutter is still winking. That woman never sleeps."},
        {"elena", "Whatever papers she left need more than a windy terrace. One hall, one table."},
        {"adrian", "I volunteer to carry chairs. I'm told it's the one thing I do well."},
    }},
    {key="restore-46", phase="restore", level=46, building="Harbour lodge", lines={
        {"mara", "One table for the whole crew, and red mullet for twelve. Adrian, that's my elbow."},
        {"tomas", "Ines's harbour log, dry on the lodge shelf. The crack grows a finger each spring tide."},
        {"elena", "Page three says \"bypass\", with no drawing. The last page is torn out."},
    }},
    {key="after-47", phase="after", level=47, lines={
        {"mara", "A page stuck in the salt crust on the steps. Same pencil as the tally!"},
        {"elena", "\"Six feet,\" underlined twice. \"Plans in the chart cabinet, no.\" Then it tears off."},
        {"tomas", "Six feet from what? And a cabinet without a number."},
    }},
    {key="after-48", phase="after", level=48, lines={
        {"tomas", "The stone gauge by the lantern steps. She took every reading there."},
        {"mara", "It's under a snarling jaguar and a metre of ferns. It looks pleased to be found."},
        {"elena", "Clear it. If she measured six feet, she'll have left a mark."},
    }},
    {key="after-49", phase="after", level=49, lines={
        {"elena", "There's the six-foot notch, deep as a thumb. And a 7 cut right beside it."},
        {"tomas", "A gauge reads tides. It has no use for a 7. I never cut that."},
        {"mara", "Then it's her handwriting, in stone. What is she counting?"},
    }},
    {key="after-50", phase="after", level=50, lines={
        {"mara", "Rain on the quay, and the crack is spitting water like a cross whale."},
        {"tomas", "A finger wider than her log says. We have less time than the book promised."},
        {"elena", "Then we find her plan before the next spring tide."},
    }},
    {key="after-51", phase="after", level=51, lines={
        {"kessler", "Good evening, Mr Vale. I hear a log has turned up. I should like the records."},
        {"adrian", "Terrible line, Kessler! Wind off the sea. I'm losing you. Losing you entirely."},
        {"mara", "The sea is flat as a plate, Adrian."},
    }},
    {key="after-52", phase="after", level=52, lines={
        {"elena", "The islanders want somewhere to sit and argue. The amphitheatre is being mended for them."},
        {"tomas", "I told them about Ines tonight, at the masons' fire. I said her name, and nothing fell."},
        {"mara", "And the hut lamp burns every night now. For the boats, you tell me."},
    }},
    {key="after-53", phase="after", level=53, lines={
        {"elena", "Rereading her log. Water pushes at the foot of the wall, never the top."},
        {"mara", "So you give the sea a detour. A bypass! A scenic route."},
        {"tomas", "Ines drew circles in the sand when she was thinking. I never asked what they were."},
    }},
    {key="after-54", phase="after", level=54, lines={
        {"mara", "Tonight's answer came slower: long, long, short. She never sends the same twice."},
        {"elena", "Then she isn't a fault repeating. She's talking, and we're slow to learn the language."},
        {"tomas", "I'm looking, Ines."},
    }},
    {key="after-55", phase="after", level=55, lines={
        {"mara", "Far cliff, tide room door, half under water. And a bucket hung on the ledge."},
        {"elena", "Hung out to dry. Someone bails that room by hand, and keeps a routine."},
        {"tomas", "Ines never could abide a wet floor."},
    }},
    {key="after-56", phase="after", level=56, lines={
        {"elena", "The pearl divers sent their reef bearings. They trust the water more than any chart."},
        {"mara", "And the cartographer's house is being re-roofed. Its drawers are numbered, like her cabinet."},
        {"tomas", "She learned her numbers in that house. Cabinet, drawer, shelf."},
    }},
    {key="after-57", phase="after", level=57, lines={
        {"mara", "Adrian, why is the radio in forty pieces again?"},
        {"adrian", "It crackled. I'm adjusting the squelch. It's rather like a very small clock."},
        {"elena", "That's the third time since the Mole Walk."},
    }},
    {key="after-58", phase="after", level=58, lines={
        {"elena", "Kessler knew a log had turned up. We told nobody off the island. Who did?"},
        {"mara", "He called him Mr Vale on the radio at the Mole Walk. Adrian, why does Kessler ring you?"},
        {"adrian", "Charm, dear Mara. He rings everyone he thinks is friendly. Biscuit?"},
    }},
    {key="after-59", phase="after", level=59, lines={
        {"elena", "The cistern is low, and the gauge shows more. A 1, cut above the 7."},
        {"tomas", "One, seven. And her page says \"chart cabinet, no.\" with the number torn away."},
        {"mara", "She cut her filing system into the harbour. Cabinet seventeen!"},
    }},
    {key="before-60", phase="before", level=60, lines={
        {"elena", "Seventeen, cut where only a keeper would look. But a cabinet in which building?"},
        {"tomas", "Not the lodge. The old archive, whose door is behind the Disc of Noon."},
        {"mara", "Then we open the disc, and the archive afterwards."},
    }},
    {key="after-60", phase="after", level=60, lines={
        {"tomas", "I told myself she wasn't coming back. Somewhere in there I stopped waiting for her."},
        {"mara", "And she's at that shutter every night, still asking. That's not someone who stopped."},
        {"elena", "Then let's bring her plans out into daylight. Cabinet seventeen, in the old archive."},
    }},
    {key="before-61", phase="before", level=61, lines={
        {"elena", "Ines's gauge numbers, seven and one, point to cabinet seventeen in the old archive."},
        {"tomas", "My sister is back, and I won't meet her through a locked drawer. Let's dig it out."},
        {"adrian", "Does anyone outside this table know about the cabinet? Purely for safety, of course."},
    }},
    {key="after-61", phase="after", level=61, lines={
        {"mara", "The reeds are cut back and the archive door shows. It's a lot of door."},
        {"elena", "Damp, but dry enough inside. Cabinet seventeen may still be in there."},
        {"mara", "Then let's give the archive a roof and a proper lock."},
    }},
    {key="restore-61", phase="restore", level=61, building="Keeper's archive", lines={
        {"elena", "The archive stands, and there is cabinet seventeen. Tomas, the key?"},
        {"tomas", "The tide-room key, off my belt. Ines made both locks, so one key fits both."},
        {"elena", "It turns! And here is a plan with her signature: I. Reed. A bypass at the wall."},
        {"tomas", "She drew where the tide should go instead of into the wall. She went for this."},
        {"elena", "Open her bypass and the wall can be saved!"},
        {"adrian", "Splendid. And now I must confess something. I signed our finds over to the Society, through Kessler."},
        {"mara", "Kessler. I've wondered since the radio, Adrian."},
        {"adrian", "It bought the ship, the crew and the cocoa. It also bought a claim on the records."},
        {"elena", "And Kessler knew about the log. You told him."},
        {"adrian", "I did. I thought it harmless. It was not."},
        {"elena", "Then hear this plainly. The plans stay here."},
    }},
    {key="after-62", phase="after", level=62, lines={
        {"elena", "I have moved my notes to the far end of the table. Away from the sponsor."},
        {"adrian", "The table is small, Elena. I can hear you not speaking to me."},
        {"mara", "Cheer up. She wrote you down in the margin. In capitals."},
    }},
    {key="after-63", phase="after", level=63, lines={
        {"kessler", "Mr Vale, I expect the records promised in your agreement."},
        {"adrian", "You will hear from me shortly. I am reading the small print."},
        {"mara", "The small print has a lot of ink on it, doesn't it?"},
    }},
    {key="after-64", phase="after", level=64, lines={
        {"adrian", "Elena, I've put my own money into the quay repairs. It isn't forgiveness. It's a start."},
        {"elena", "It's a start."},
        {"mara", "No capitals this time. Progress."},
    }},
    {key="after-65", phase="after", level=65, lines={
        {"elena", "The bypass must draw from this well and carry the water off. I'm certain."},
        {"tomas", "The well is sweet water. Ines's line starts at the tide, below the wall."},
        {"elena", "Then I was wrong, and the well is innocent. Noted. In capitals."},
    }},
    {key="after-66", phase="after", level=66, lines={
        {"mara", "Tomas, could the old lighthouse guide a boat round the broken quay?"},
        {"tomas", "If its lamp turns again. It sat dark the whole time I kept the harbour."},
        {"elena", "Then light it. Her plan may show us a way ashore."},
    }},
    {key="restore-66", phase="restore", level=66, building="Lighthouse", lines={
        {"mara", "The lighthouse is lit! The beam sweeps the whole inlet like a lazy wave."},
        {"elena", "And on her plan, a second landing. Ines marked it with a cross and a bearing."},
        {"tomas", "It's on the far shore, round the point. She wanted a way ashore the wall couldn't take."},
        {"elena", "Her plan also lists a signal plate for the lamp. The lantern room's cradle is empty."},
        {"mara", "Then the beam is our guide, and the cross is our door."},
    }},
    {key="after-67", phase="after", level=67, lines={
        {"elena", "Bearings taken from the rock. They lead round the broken wall, as she drew them."},
        {"mara", "The cormorants object. Loudly. One has taken my hat."},
        {"tomas", "That's a sign of good water. Leave him the hat."},
    }},
    {key="after-68", phase="after", level=68, lines={
        {"adrian", "Elena, how do I make it right? Tell me what to do and I shall do it."},
        {"elena", "Do it, and don't ask me to say it. That's how a person makes anything right."},
        {"mara", "Ooh. Adrian, I'd write that one down. Elena rarely hands out advice for free."},
    }},
    {key="after-69", phase="after", level=69, lines={
        {"tomas", "The stair to the second landing is dry only at low water. Not a stone moved. Ines picked well."},
        {"mara", "Whoever wrecked that ship picked worse. It's lodged in the gate like a cork."},
        {"elena", "We go round it. Mind the slime."},
    }},
    {key="after-70", phase="after", level=70, lines={
        {"elena", "Low tide at last. The wall is measured, and it matches Ines's mark to the finger."},
        {"tomas", "Six feet of cut, as she wrote. Her plan was right before we ever read it."},
        {"mara", "The jaguar's mouth is clean, too. I'd say we've been forgiven."},
    }},
    {key="after-71", phase="after", level=71, lines={
        {"mara", "Look at the schooner on the beach. Its skiff is rotten, but the keel's good."},
        {"tomas", "That stair is dry only at low water. A boat could reach the landing at any tide."},
        {"mara", "Give me boards and tar, and the schooner's skiff will carry us there."},
    }},
    {key="after-72", phase="after", level=72, lines={
        {"mara", "Nets in the loft, dry as the day they were hung. Someone knew what to save."},
        {"elena", "The islanders who work the quay keep their own records, if asked. I'm asking."},
        {"tomas", "Ask the old netmen. They remember every storm."},
    }},
    {key="after-73", phase="after", level=73, lines={
        {"tomas", "I promised her the warning would stay lit. Then the cable broke, and I let it."},
        {"mara", "You didn't let it. You rigged a reel from a log."},
        {"tomas", "Late is better than never. Let's go on."},
    }},
    {key="after-74", phase="after", level=74, lines={
        {"elena", "From the sea the island is a dark lump. We need something tall and distinct."},
        {"mara", "A star observatory? Planned, I mean. It's not up yet."},
        {"elena", "Plans are all we have. I've marked its site on the chart."},
    }},
    {key="after-75", phase="after", level=75, lines={
        {"mara", "The old stair goes right under the inlet. At full tide it's a swimming bath."},
        {"tomas", "At low tide, a path to the far station. Ines uses it. Her chalk is on the fifth step."},
        {"elena", "Smudged, not faded. She was here this week."},
    }},
    {key="after-76", phase="after", level=76, lines={
        {"elena", "The star dome will be the landmark for any boat at dusk."},
        {"mara", "If the schooner's skiff floats. The tar is drying slowly and has opinions."},
        {"elena", "Bearings, then tar. In that order."},
    }},
    {key="after-77", phase="after", level=77, lines={
        {"tomas", "Ines marked a stone here for the tide. It sits right where the bypass begins."},
        {"mara", "You two did love your marks."},
        {"tomas", "She'd have called it good order. I called it getting in her way."},
    }},
    {key="after-78", phase="after", level=78, lines={
        {"adrian", "I've asked a lawyer in town. She read my agreement and laughed. For eleven minutes."},
        {"elena", "Is that good?"},
        {"adrian", "The laugh, yes. The agreement, less so. There is a way out. It costs me."},
    }},
    {key="after-79", phase="after", level=79, lines={
        {"mara", "The lighthouse lamp turns smoothly now. I could watch it all night."},
        {"tomas", "Don't. Someone must be fresh for the wall."},
        {"elena", "The wall first. Then Ines, with the light behind her."},
    }},
    {key="before-80", phase="before", level=80, lines={
        {"elena", "The plan, the second landing, the measured wall. Everything fits but the water."},
        {"tomas", "The vault below the quay is where the tide first bites. We start there."},
        {"adrian", "I'll keep the radio. In case someone calls. Someone usually does."},
    }},
    {key="after-80", phase="after", level=80, lines={
        {"kessler", "Mr Vale, a boat will come for the records in twelve days. Have them ready."},
        {"adrian", "Twelve days. Noted. I am reading, and reading, and reading."},
        {"elena", "Twelve days. We finish Ines's plan first, and the records stay put."},
    }},
    {key="before-81", phase="before", level=81, lines={
        {"elena", "Kessler has named his date. Ines's plan is our answer, and the records stay put."},
        {"tomas", "She marked a second landing for us. She never meant us to fight the quay."},
        {"mara", "Then I'll polish my lamp. If she answers, I want a clean flash."},
    }},
    {key="after-81", phase="after", level=81, lines={
        {"mara", "Kites off the top stair! The islanders' children are flying them over the old roofs."},
        {"elena", "The first family has chalked its house outline on the stones. Others are following."},
        {"tomas", "Then the quay needs a warning notice before anyone moves in. A harbour with nobody home is a quay."},
    }},
    {key="after-82", phase="after", level=82, lines={
        {"mara", "Thick mist down here. I flashed my lamp and lit up one very surprised frog."},
        {"tomas", "That's why the old keepers kept a bell as well as a lamp. Never trust one signal."},
        {"elena", "Lamp, bell and shutter. Writing that down."},
    }},
    {key="after-83", phase="after", level=83, lines={
        {"elena", "The idol's crusted with salt. The sea once reached this terrace. How high, Tomas?"},
        {"tomas", "The old keepers cut tide marks into its base. Ines copied them into her log."},
        {"adrian", "I'll pay for a proper survey. Be gentle, Elena. I'm out of practice at generosity."},
    }},
    {key="after-84", phase="after", level=84, lines={
        {"kessler", "The Society will collect the records on the named date, Mr Vale. All of them."},
        {"elena", "Ines drew those records to save a wall. They're not stock for a shelf."},
        {"adrian", "I'm drafting my answer. Give me a few days."},
    }},
    {key="after-85", phase="after", level=85, lines={
        {"mara", "A coiled serpent! Oh. It's carved. I shouted at a carving, and nobody saw."},
        {"elena", "I saw. I write down what we saw, not what we hoped."},
        {"tomas", "Its tail points to the lantern steps. The old builders liked a joke with a direction."},
    }},
    {key="after-86", phase="after", level=86, lines={
        {"mara", "Rush Landing! Reeds cut back, and a clear stair down to deep water."},
        {"tomas", "Ines's second landing, plain as her handwriting. Deep water and a dry stair."},
        {"elena", "Once the wall is safe, I want a museum for our finds. Doors open to every islander."},
    }},
    {key="after-87", phase="after", level=87, lines={
        {"mara", "Embers along the colonnade, and Adrian writing by lantern since supper."},
        {"adrian", "One sentence. It's taking me all night. It says 'surrender'."},
        {"tomas", "Keep it plain. Ines never could stand a long letter."},
    }},
    {key="after-88", phase="after", level=88, lines={
        {"adrian", "Kessler, I surrender the claim. The records stay here."},
        {"kessler", "That will be expensive, Mr Vale."},
        {"adrian", "Worth every penny. Send the bill to me."},
    }},
    {key="after-89", phase="after", level=89, lines={
        {"tomas", "My father watched for boats from this tier. I watched for a lamp."},
        {"mara", "And now one answers every night."},
        {"tomas", "Then I stop only watching. From tonight I answer her flash for flash. Months of silence are enough."},
    }},
    {key="after-90", phase="after", level=90, lines={
        {"elena", "The light below flashes faster, short and sharp. A distress call! She's in trouble!"},
        {"tomas", "No. It's the old tide count, one flash for each hour the water rises."},
        {"mara", "So she's minding our tide from down there. Elena, you can write \"wrong\" now."},
    }},
    {key="after-91", phase="after", level=91, lines={
        {"mara", "Parrots on every step. That one just said \"expensive, Mr Vale\"."},
        {"adrian", "I will not be taking questions about the parrot."},
        {"tomas", "The temple is the place for our quay notice. Every worker passes it."},
    }},
    {key="restore-91", phase="restore", level=91, building="Temple of the Sun", lines={
        {"tomas", "The warning's on the temple wall, where every worker passes. The museum crowd too."},
        {"elena", "Behind the altar, a bronze plate with a slot: the signal plate Ines's plan lists!"},
        {"mara", "It'll fit my lamp, or I'll make it. Give me a file and a day."},
    }},
    {key="after-92", phase="after", level=92, lines={
        {"tomas", "Lowest tide of the month. I'm chalking a mark at the foot of the wall."},
        {"elena", "If the bypass works, the chalk stays dry at the next flood. If not, it washes out."},
        {"mara", "Tomas, you've got chalk on your ear. The aviary parrots are laying odds."},
    }},
    {key="after-93", phase="after", level=93, lines={
        {"elena", "The chart scrap from the well shows Tern Rock Light, and a second lamp beyond it."},
        {"tomas", "Stone, timber and lime are stacked at the landing. The wall has what it needs."},
        {"mara", "And a tern on my head. Rude."},
    }},
    {key="after-94", phase="after", level=94, lines={
        {"elena", "The cistern bell rings when water enters it. The keepers could hear the tide."},
        {"tomas", "Ines routed her bypass through it, then out to the fountain."},
        {"mara", "A wall that tells you when it's working. I like her already."},
    }},
    {key="after-95", phase="after", level=95, lines={
        {"mara", "A whole mast, beached. Somebody lost an argument with a storm."},
        {"tomas", "It makes the best lever on the island. Ines's plan says: mast moves the sluice stone."},
        {"elena", "Then everyone lifts on three. Not on \"wait\". On three."},
    }},
    {key="after-96", phase="after", level=96, lines={
        {"mara", "Light through the fern window falls straight on the sluice stone. An easy morning, for once."},
        {"tomas", "Ines would call that a good omen. Then she'd check the sluice twice."},
        {"elena", "The stone turns. Water's heading for the fountain."},
    }},
    {key="restore-96", phase="restore", level=96, building="Jade fountain", lines={
        {"elena", "Jade water! It comes straight from Ines's bypass. Tomas, your chalk mark?"},
        {"tomas", "Dry. Dry at the flood and dry at the turn. The bypass works, just as she drew it."},
        {"mara", "Then the wall is safe. Now we tell her."},
    }},
    {key="after-97", phase="after", level=97, lines={
        {"elena", "The cartouche on the fountain reads: no keeper keeps alone."},
        {"adrian", "Kessler's invoice arrived, with a footnote about its own footnotes. I'm paying it gladly."},
        {"tomas", "Then you've earned a chair at the lodge table, Adrian."},
    }},
    {key="after-98", phase="after", level=98, lines={
        {"mara", "Idols between the fruit trees. I've decided they don't mind me stealing a plum."},
        {"elena", "The skiff is stocked, the lamp is clean, and a lantern burns at the second landing."},
        {"tomas", "She'll see it from the far cliff. We wait for the turn of the tide."},
    }},
    {key="after-99", phase="after", level=99, lines={
        {"tomas", "Hold the plate steady. I fitted this lamp once with Ines. My hands remember."},
        {"elena", "Look: a lantern moving down the far cliff, step by step, to the second landing."},
        {"mara", "Tomas, your hands are shaking."},
    }},
    {key="before-100", phase="before", level=100, lines={
        {"mara", "The signal plate's in the lamp. Time for the long flash."},
        {"tomas", "I'll take the key down to meet her."},
        {"elena", "The tide's turning. Go carefully, both of you."},
    }},
    {key="after-100", phase="after", level=100, lines={
        {"mara", "Long flash out, and three back with a pause before the third. That's her answer!"},
        {"tomas", "Welcome home, Ines. Here's the key. We'll keep the light together."},
        {"ines", "Gladly. The quay would have had me, so I came round by the far shore and worked the shutter by hand."},
        {"ines", "I changed its tune till a lamp I could trust answered. And this one did."},
        {"ines", "I've brought a chart of the other lights. They need keepers too."},
    }},
}
